// Property function for Socket Count (adds sockets to an item).
// Property→Stat Conversion:
// - Property code: ? (socket property)
// - Target: Item flags + socket count field
// - Formula: property.param → socket count (no RNG)
// Property data (pProperty):
// - fparam: socket count value
// Logic:
// 1. Validate property pointer is not NULL
// 2. Set ITEMFLAG_SOCKETED flag on item
// 3. Call ITEM_SetSocketCount with value from property.param
// This function does NOT use the stat system - it directly modifies the item's
// socketed flag and socket count fields.
// No randomization - the socket count is fixed from the property definition.
// Used by:
// - Runewords (fixed socket requirements)
// - Unique items with sockets (e.g., Harlequin Crest has 2 sockets)
// - Set items with sockets
// - Cube recipes that add sockets
// Error: If pProperty==NULL, calls Fog::ErrorManager::ERROR (line 0x312)
int32_t __fastcall ITEMMOD_ApplySocketCount(int32_t nType, D2UnitStrc * pUnit, D2UnitStrc * pItemUnit, D2SetsTxtFStrc * pProperty, eD2UnitStat eStatCode, int32_t nParam2, int32_t nParam3, uint32_t nParam, int32_t nContext) {
    if (!pProperty) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x312);
      exit(-1);
    }

    Items::ITEM_EditItemData_eItemFlag(pItemUnit, ITEMFLAG_SOCKETED, 1);
    Items::ITEM_SetSocketCount(pItemUnit, (uint32_t)pProperty->fparam);
    return 1;
}

// Property function for Indestructible (makes item unbreakable).
// Property→Stat Conversion:
// - Property code: ? (indestructible property)
// - Target stats: maxdurability, durability
// - Formula: Sets both to 0 (special flag value)
// Logic:
// 1. Determine target item (nContext if non-NULL and its unit type is 4 (UNIT_ITEM), else pItemUnit)
// 2. Set UNITSTAT_maxdurability = 0
// 3. Set UNITSTAT_durability = 0
// Setting durability stats to 0 is the game's way of marking an item as
// indestructible. The display code interprets 0 durability as "Indestructible"
// rather than "Broken".
// Used by:
// - Indestructible affix (appears on eth items or as property)
// - Unique items with inherent indestructibility
// - Runewords that grant indestructibility (e.g., Breath of the Dying)
// This overrides the item's normal durability values, making it immune to
// durability loss from use or being hit.
int32_t __fastcall ITEMMOD_ApplyIndestructible(int32_t nType, D2UnitStrc * pUnit, D2UnitStrc * pItemUnit, D2SetsTxtFStrc * pProperty, eD2UnitStat eStatCode, int32_t nParam2, int32_t nParam3, uint32_t nParam, int32_t nContext) {
    if (!nContext || *(int*)nContext != 4) {
      nContext = (int32_t)pItemUnit;
    }

    Stats::StatsEx::STATLIST_SetUnitStat((D2UnitStrc*)nContext, UNITSTAT_maxdurability, 0, 0);
    Stats::StatsEx::STATLIST_SetUnitStat((D2UnitStrc*)nContext, UNITSTAT_durability, 0, 0);
    return 1;
}

