      pSeed = Items::GetItemSeed(pItemUnit);
      nClassSkillLayer = D2Client::Archive::RANDOM_RandomNumberSelector(pSeed, nClassSkillLayer);
      nValue = nClassSkillLayer + nRangeLow;
