// Checks whether an item matches the repair eligibility described by szRepairModes byte flags. Tests melee weapons (excl. staves/bows/crossbows/scepters/wands) against flag [1], body armor (excl. shields/boots/gloves/belts) against flag [0], then falls through a table of 9 specific item types (Shield, Scepter, Wand, Staff, Bow, Crossbow, Boots, Gloves, Belt) each paired with an individual mode flag. Returns 1 on match, 0 otherwise.
uint32_t __stdcall ITEMMOD_MatchesRepairType(D2UnitStrc * pUnit, char * szRepairModes) {
    uint32_t bIsArmor;
    D2RepairTypeEntryStrc eTypeEntry0[9];
    eTypeEntry0[0].byMode = szRepairModes[2];
    eTypeEntry0[1].byMode = szRepairModes[3];
    eTypeEntry0[2].byMode = szRepairModes[4];
    eTypeEntry0[3].byMode = szRepairModes[5];
    eTypeEntry0[4].byMode = szRepairModes[6];
    eTypeEntry0[6].byMode = szRepairModes[7];
    eTypeEntry0[7].byMode = szRepairModes[8];
    eTypeEntry0[8].byMode = szRepairModes[9];
    eTypeEntry0[0].eType = ITEMTYPE_Shield;
    eTypeEntry0[1].eType = ITEMTYPE_Scepter;
    eTypeEntry0[2].eType = ITEMTYPE_Wand;
    eTypeEntry0[3].eType = ITEMTYPE_Staff;
    eTypeEntry0[4].eType = ITEMTYPE_Bow;
    eTypeEntry0[5].eType = ITEMTYPE_Crossbow;
    eTypeEntry0[6].eType = ITEMTYPE_Boots;
    eTypeEntry0[7].eType = ITEMTYPE_Gloves;
    eTypeEntry0[8].eType = ITEMTYPE_Belt;
    eTypeEntry0[5].byMode = eTypeEntry0[4].byMode;
    eD2ItemTypes eItemType = Items::ITEM_GetItemData_wType(pUnit);
    if (szRepairModes[1] != '\0') {
      uint32_t bIsTypeMatch;
      bIsTypeMatch = Items::ITEMS_IsA(pUnit, ITEMTYPE_Weapon);
      if (bIsTypeMatch && eItemType != ITEMTYPE_Staff && eItemType != ITEMTYPE_Bow && eItemType != ITEMTYPE_Crossbow && eItemType != ITEMTYPE_Scepter && eItemType != ITEMTYPE_Wand) {
        return 1;
      }
    }
    if (*szRepairModes != '\0') {
      bIsArmor = Items::ITEMS_IsA(pUnit, ITEMTYPE_AnyArmor);
      if (bIsArmor && eItemType != ITEMTYPE_Shield && eItemType != ITEMTYPE_Boots && eItemType != ITEMTYPE_Gloves && eItemType != ITEMTYPE_Belt) {
        return 1;
      }
    }

    uint32_t nTypeIdx = 0;
    while (eItemType != eTypeEntry0[nTypeIdx].eType || eTypeEntry0[nTypeIdx].byMode == '\0') {
      nTypeIdx++;
      if (nTypeIdx >= 9) {
        return 0;
      }
    }

    return 1;
}

void __stdcall ITEMMOD_RollGemRuneType(D2UnitStrc * pUnit) {
    // Static local variables (originally global data)
    static uint32_t gaGemRuneTypeIds[6] = { 0x0, 0x1, 0x2, 0x3, 0x9, 0x7 }; D2_STATIC_GUARD(gaGemRuneTypeIds, "D2Common::ITEMS::ItemMods::ITEMMOD_RollGemRuneType::gaGemRuneTypeIds");
    static uint32_t gaGemRuneTypeTable = 0x6; D2_STATIC_GUARD(gaGemRuneTypeTable, "D2Common::ITEMS::ItemMods::ITEMMOD_RollGemRuneType::gaGemRuneTypeTable");

    D2SeedStrc seedAdvanced;
    uint32_t nTableSize = gaGemRuneTypeTable;
    D2SeedStrc* pSeed = Items::GetItemSeed(pUnit);
    if ((int)nTableSize <= 0) {
      nTableSize = 0;
    } else if (nTableSize & nTableSize - 1) {
      seedAdvanced = D2_SEED_NEXT(*pSeed);
      pSeed->nSeedHigh = seedAdvanced.nSeedHigh;
      pSeed->nSeedLow = seedAdvanced.nSeedLow;
      nTableSize = (uint32_t)(seedAdvanced.nSeedLow % nTableSize);
    } else {
      seedAdvanced = D2_SEED_NEXT(*pSeed);
      pSeed->nSeedHigh = seedAdvanced.nSeedHigh;
      pSeed->nSeedLow = seedAdvanced.nSeedLow;
      nTableSize = nTableSize - 1 & seedAdvanced.nSeedLow;
    }

    Items::ITEM_SetItemData_nFileIndex(pUnit, gaGemRuneTypeIds[nTableSize]);
    if (gaGemRuneTypeIds[nTableSize] != 9 && gaGemRuneTypeIds[nTableSize] != 7) {
      Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_value, 1, 0);
      return;
    }

    pSeed = Items::GetItemSeed(pUnit);
    seedAdvanced = D2_SEED_NEXT(*pSeed);
    pSeed->nSeedHigh = seedAdvanced.nSeedHigh;
    pSeed->nSeedLow = seedAdvanced.nSeedLow;
    Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_value, ((seedAdvanced.nSeedLow & 3) + 1) * 0x100, 0);
}

// Rolls a random integer in [nMin, nParam] using the item's seed (via GetItemSeed for UNIT_ITEM, pUnit->sSeed otherwise). If min==max returns min with no RNG call. Returns the rolled value in EAX.
int32_t __fastcall ITEMMOD_RollRandomValue(D2UnitStrc * pUnit, int32_t nMin, int32_t nParam) {
    uint32_t nRolled;
    int32_t nLow = nMin;
    if (nParam == nMin) {
      return nLow;
    }
    if (nParam < nMin) {
      nLow = nParam;
      nParam = nMin;
    }
    if (!pUnit || pUnit->eUnitType != UNIT_ITEM) {
      if (nLow < nParam) {
        nRolled = D2Client::Archive::RANDOM_RandomNumberSelector(&pUnit->sSeed, nParam - nLow + 1);
        return nRolled + nLow;
      }
    } else {
      D2SeedStrc* pSeed;
      pSeed = Items::GetItemSeed(pUnit);
      if (nLow < nParam) {
        nRolled = D2Client::Archive::RANDOM_RandomNumberSelector(pSeed, nParam - nLow + 1);
        return nRolled + nLow;
      }
    }

    return nLow;
}

// Adds a stat to an item's stat list. Validates stat ID against ItemStatCost table, then calls ITEMMOD_GetOrCreateStatList to obtain or create the target stat list. Adds the shifted stat value via STATLIST_AddStatValue or D2AddStatToStatsListEx depending on nParam2. Special-cases poison (stat 0x3A) to also add/check UNITSTAT_poison_count. Returns nParam3 (the stat value) on success, 0 on invalid stat or missing stat list.
