uint32_t __fastcall ITEMPROP_AddStat_WithMaxDurabilityReset(int32_t nParam1, D2UnitStrc * pUnit, D2UnitStrc * pUnit2, uint32_t nPropPtr, int32_t nParam2, int32_t nParam3, uint32_t dwParam1, uint32_t dwParam2, int32_t nParam4, uint32_t nStatLayer, uint32_t dwParam3) {
    if (!(nPropPtr && pUnit2)) {
      return 0;
    }
    if (pUnit2->eUnitType == UNIT_ITEM && nParam1 == 1) {
      ITEMMOD_MaximizeStatForEnhanced((int)(short int)nParam3, pUnit2);
    }

    int32_t nMaxDurability = ITEMMOD_RollRandomValue(pUnit2, *(int32_t*)(nPropPtr + 8), *(int32_t*)(nPropPtr + 0xc));
    uint32_t uRetVal = ITEMMOD_AddStatToItem(pUnit2, nStatLayer, pUnit, nPropPtr, nParam2, (short int)nParam3, 0, nMaxDurability, nParam4);
    if (uRetVal) {
      nMaxDurability = Stats::StatsEx::GetTxtMaxDurability(pUnit2);
      if (nMaxDurability <= 0) {
        return uRetVal;
      }

      Stats::StatsEx::STATLIST_SetUnitStat(pUnit2, UNITSTAT_durability, nMaxDurability, 0);
      return uRetVal;
    }

    return 0;
}

uint32_t __fastcall ITEMPROP_ApplyEthereal(uint32_t dwParam1, D2UnitStrc * pUnit, D2UnitStrc * pUnit2, uint32_t nParam1, uint32_t dwParam2, int32_t nParam, uint32_t dwParam3, uint32_t dwParam4, int32_t nParam2, uint32_t nParam3, uint32_t dwParam5) {
    if (!(nParam1 && pUnit2 && pUnit2->eUnitType == UNIT_ITEM)) {
      return 0;
    }

    uint32_t uRetVal = Items::ITEM_GetItemData_eD2ItemFlag_IsEthereal(pUnit2);
    if (uRetVal) {
      return 0;
    }

    uRetVal = Items::ITEM_CheckIfItemHasDurability(pUnit2);
    if (uRetVal) {
      ITEMMOD_ApplyEtherealBonus(pUnit2);
      return 1;
    }

    return 0;
}

// Already-documented (existing description is accurate and detailed — expansion property pipeline iterating up to 7 func slots from D2PropertiesTxt).
void __stdcall ITEMMOD_ApplyPropertyToUnitStatsExpansion(uint32_t dwParam1, D2UnitStrc * pUnit, D2UnitStrc * pUnit2, uint32_t dwParam2, uint32_t dwParam3, uint32_t dwParam4, D2SetsTxtFStrc * pSetsTxtF, int32_t nParam, uint32_t nParam2, uint32_t dwParam5) {
    // Static local variables (originally global data)
    static int PropertiesFuncCount = 0x25; D2_STATIC_GUARD(PropertiesFuncCount, "D2Common::ITEMS::ItemMods::ITEMMOD_ApplyPropertyToUnitStatsExpansion::PropertiesFuncCount");

    if (!pSetsTxtF) {
      return;
    }

    int nFuncCode = pSetsTxtF->fcode;
    if (!(nFuncCode >= 0 && nFuncCode < sgptDataTable->nTxtPropertiesSize)) {
      return;
    }

    D2PropertiesTxt* pPropTxt = sgptDataTable->pTxtProperties + nFuncCode;
    if (!pPropTxt) {
      return;
    }

    uint32_t nFuncIdx = 0;
    nFuncCode = 0;
    do {
      uint32_t nFuncRetVal;
      if ((int)(uint32_t)(uint8_t)pPropTxt->func[nFuncCode] >= PropertiesFuncCount) {
        return;
      }
      if (!PROPERTIESFUNCTIONS[(uint8_t)pPropTxt->func[nFuncCode]]) {
        return;
      }

      nFuncRetVal = (*PROPERTIESFUNCTIONS[(uint8_t)pPropTxt->func[nFuncCode]])(dwParam1, pUnit, pUnit2, (uint32_t)pSetsTxtF, (uint32_t)(uint8_t)pPropTxt->set[nFuncCode], (uint32_t)(uint16_t)pPropTxt->stat[nFuncCode], (uint32_t)(uint16_t)pPropTxt->val[nFuncCode], nFuncIdx, nParam, nParam2, dwParam5);
      if (!nFuncCode) {
        nFuncIdx = nFuncRetVal;
      }

      nFuncCode++;
    } while (nFuncCode < 7);
}

